// =========================================================================
// ULTRA-GOAL PBR TEXTURE LOADER & PROCEDURAL FALLBACK (Three.js)
// Carga mapas PBR o los genera dinÃ¡micamente en memoria vÃ­a CanvasTexture
// =========================================================================
import * as THREE from 'https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.module.js';

export class PBRTextureManager {
    constructor() {
        this.loader = new THREE.TextureLoader();
        this.cache = new Map();
    }

    // Carga texturas desde archivos en disco o URLs
    loadPBRMaterial(basePath, textureName, repeat = { x: 4, y: 4 }) {
        const diffuse = this.loader.load(`${basePath}/${textureName}_diffuse.png`);
        const normal = this.loader.load(`${basePath}/${textureName}_normal.png`);
        const roughness = this.loader.load(`${basePath}/${textureName}_roughness.png`);

        [diffuse, normal, roughness].forEach(tex => {
            tex.wrapS = THREE.RepeatWrapping;
            tex.wrapT = THREE.RepeatWrapping;
            tex.repeat.set(repeat.x, repeat.y);
        });

        return new THREE.MeshStandardMaterial({
            map: diffuse,
            normalMap: normal,
            roughnessMap: roughness,
            roughness: 0.8,
            metalness: 0.2
        });
    }

    // Generador instantÃ¡neo procedural en VRAM (Cero dependencias externas)
    createProceduralCanvasTexture(type = 'asphalt', size = 512) {
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');

        ctx.fillStyle = type === 'asphalt' ? '#2b2b2b' : '#8b4513';
        ctx.fillRect(0, 0, size, size);

        // Ruido y gravilla
        for (let i = 0; i < 25000; i++) {
            const x = Math.random() * size;
            const y = Math.random() * size;
            const lum = Math.floor(Math.random() * 80 + 30);
            ctx.fillStyle = `rgb(${lum},${lum},${lum})`;
            ctx.fillRect(x, y, 1.5, 1.5);
        }

        const texture = new THREE.CanvasTexture(canvas);
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        return texture;
    }
}
